// here. Once the grant is updated to include `StateHandle<'...', read-write>`,
// add `import aap:caps/state-rw@0.1.0;` to the world and a `state_rw::put` call
// at the top of `run`. Output is unaffected either way.

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            // A refused (out-of-allowlist) URL traps at the boundary and is not
            // caught here. A failed transport comes back as `Err` and is recorded.
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch { documents, failures }
    }
}

